/**
 * Nguồn sự thật của dữ liệu seed `province`/`ward` (danh mục hành chính Tỉnh/Phường-Xã toàn
 * hệ thống, theo cải cách sáp nhập hành chính 2025 — mã do Bộ Nội vụ ban hành) — dùng bởi seed
 * script (apps/api) và test. Sửa danh sách thì sửa ở đây, không sửa trực tiếp dữ liệu trong DB
 * (seed idempotent, chạy lại để đồng bộ).
 *
 * Dữ liệu lấy nguyên văn từ file chủ dự án cung cấp (`docs/data/Danh-muc-Phuong-xa_moi.md`) —
 * không tự thêm/bớt/sửa chính tả. `code` tỉnh = cột "Mã tỉnh (BNV)" (1..34); `code` phường/xã =
 * cột "Mã phường/xã mới" (8 chữ số, duy nhất toàn quốc — đã xác nhận không trùng giữa các tỉnh).
 * `sortOrder` của ward = thứ tự xuất hiện trong file, tính lại từ 1 theo từng tỉnh.
 *
 * **Ngoại lệ đã sửa theo yêu cầu chủ dự án**: 4 tên tỉnh dùng viết tắt "Tp" trong file gốc (Hải
 * Phòng, Đà Nẵng, Hồ Chí Minh, Cần Thơ) đã đổi thành "Thành phố" đầy đủ cho nhất quán với các
 * thành phố trực thuộc trung ương khác (Hà Nội, Huế) — không đổi gì khác ngoài 4 tên này.
 */

export interface ProvinceSeedItem {
  code: string;
  name: string;
  sortOrder: number;
}

export interface WardSeedItem {
  code: string;
  name: string;
  provinceCode: string;
  sortOrder: number;
}

